    def __getitem__(self, key):
        return Undefined(self.name + "[" + str(key) + "]")

    def __str__(self):
        return ""

    def __repr__(self):
        return ""

    def __bool__(self):
        return False

    def __iter__(self):
        return iter(())


def _lookup(context, name):
    if isinstance(context, dict):
        return context.get(name, Undefined(name))
    return getattr(context, name, Undefined(name))


def _attr(value, name):
    if isinstance(value, dict):
        return value.get(name, Undefined(name))
