        "range": range, "dict": dict, "list": list, "tuple": tuple,
        "len": len, "str": str, "int": int, "float": float,
        "bool": bool, "min": min, "max": max, "sum": sum,
        "enumerate": enumerate, "zip": zip, "abs": abs,
        "sorted": sorted, "reversed": reversed,
